/**
 * US-17 — clasificar (router de intenciones de Telegram).
 *
 * Un bot de Telegram admite UN solo webhook. Este nodo recibe todos los
 * updates del bot, valida el secreto del webhook y decide la intención con
 * reglas deterministas, sin LLM:
 *
 *   1. Foto o imagen                         -> receta     (US-09)
 *   2. aprobar/rechazar FAR-XXXX (farmacéutico) -> aprobacion (US-20)
 *   3. en ruta/entregado FAR-XXXX (personal)  -> despacho   (US-22)
 *      revisar vencidos (personal)            -> expiracion (US-10 a demanda)
 *   4. Riesgo vital o autolesión              -> respuesta de contención (RNF-08)
 *   5. Pregunta clínica (dosis, síntomas)     -> respuesta sin consejo clínico (RNF-08)
 *   6. Saludo, /start o ayuda                 -> bienvenida con el menú
 *   7. reservar/encargar/apartar ...          -> reserva    (US-05)
 *   8. Código FAR-XXXX, RUT o "estado"        -> estado     (US-06)
 *   9. Horario, dirección u otros trámites    -> respuesta: fuera del dominio
 *  10. Resto: nombre de un remedio            -> consulta   (US-04)
 *  11. Texto largo sin regla                  -> ambiguo (Gemini opcional; si no, menú)
 *
 * El router además NORMALIZA el texto antes de derivarlo: quita saludos y
 * muletillas ("hola, ¿hay pregavalina 75?" -> "pregavalina 75"), porque el
 * buscador difuso de US-04/US-05 promedia todas las palabras y las muletillas
 * bajan el puntaje bajo el umbral. El texto normalizado viaja en
 * body.message.text; el original queda en texto_original.
 *
 * Salida: UN ítem { intent, chat_id, reply, texto_original, texto_limpio,
 * llm_disponible, headers, body } o [] (secreto inválido o update sin
 * mensaje). headers y body se reenvían al subflujo, que vuelve a validar el
 * secreto (defensa en profundidad). Nunca lanza excepciones.
 */

const MENSAJES = {
  bienvenida:
    'Hola, soy el asistente virtual de la Farmacia Comunitaria de Peñalolén (prototipo).\n' +
    'Soy un programa automático: respondo solo con los datos de la planilla oficial de la farmacia y no doy indicaciones médicas.\n\n' +
    'Puede escribirme:\n' +
    '• El nombre de un remedio, por ejemplo: pregabalina 75\n' +
    '• Para reservar: reservar neurogab 75 x1 rut 11.111.111-1, Av. Grecia 8735, Peñalolén Alto\n' +
    '• Para ver su pedido: estado #FAR-0001, o su RUT\n' +
    '• Para enviar su receta: una foto con el código #FAR-0001 escrito en el texto de la foto\n\n' +
    'Si reserva, usamos su RUT y su dirección solo para gestionar el pedido. Ante una urgencia, llame al SAMU 131.',
  urgencia:
    'Si es una urgencia, llame ahora al SAMU 131 o acuda al SAPU más cercano. ' +
    'Este asistente no puede atender emergencias médicas.',
  autolesion:
    'Si está pensando en hacerse daño, no está solo ni sola. Llame ahora a la línea *4141 ' +
    '(gratuita, 24 horas, desde celulares) o al SAMU 131.',
  consejo:
    'No puedo dar indicaciones sobre dosis, síntomas ni tratamientos. Consulte a su médico o al ' +
    'químico farmacéutico de la farmacia. Si es una urgencia, llame al SAMU 131.',
  estado_sin_dato:
    'Para ver su pedido, escriba su código (por ejemplo: estado #FAR-0001) o su RUT (por ejemplo: 11.111.111-1).',
  sin_texto:
    'Por ahora solo puedo leer mensajes de texto y fotos de recetas. Escriba el nombre del remedio que busca.',
  fuera_de_dominio:
    'Por ahora solo puedo ayudarle con remedios (stock y precio), reservas, recetas y el estado de su pedido. ' +
    'Para horarios, dirección u otros trámites, consulte el sitio web de la Municipalidad de Peñalolén.',
  no_entendido:
    'No logré entender su mensaje. Escriba el nombre del remedio (por ejemplo: losartán 50), ' +
    '"estado" y su código #FAR, o "ayuda" para ver todas las opciones.'
};

const RE_FAR = /#?\s*FAR\s*-?\s*(\d{4})\b/i;
const RE_RUT = /\b\d{1,2}\.?\d{3}\.?\d{3}\s*-\s*[\dkK]\b/;
// Mismo patrón que parse_pharmacist_command de US-20 (contrato entre router y subflujo).
const RE_CMD_FARMACEUTICO = /^\s*\/?\s*(aprobar|rechazar)\s+#?FAR-\d{4}\b/i;
const RE_CMD_PERSONAL = /^\s*\/?\s*(en\s+ruta|ruta|despachar|entregado|entregar)\s+#?\s*FAR-?\d{4}\b/i;
// El personal puede ejecutar a demanda la liberación de reservas vencidas (US-10).
const RE_CMD_EXPIRACION = /^\s*\/?\s*(revisar\s+vencidos|expirar\s+vencidos)\s*$/i;
const RE_PALABRA_RESERVA = /(?:^|[^a-záéíóúñ])(reservar|reserva|res[eé]rvame|encargar|encargo|comprar|apartar|lo\s+quiero)(?![a-záéíóúñ])/i;
const RE_ESTADO = /\b(estado|seguimiento|mi\s+pedido|mi\s+orden|donde\s+(viene|va|esta)|cuando\s+llega)\b/;
const MAX_PALABRAS_CONSULTA = 6;
// Preguntas que no son de remedios ni pedidos (horario, ubicación, trámites).
const RE_FUERA_DOMINIO = /\b(horario|horarios|a que hora|abren|cierran|atienden|direccion|ubicacion|donde queda|donde estan|telefono de la farmacia|inscribir|inscripcion|inscribirme)\b/;

// Frases normalizadas (minúsculas y sin tildes) que activan la contención.
const FRASES_AUTOLESION = ['suicid', 'quitarme la vida', 'matarme', 'hacerme dano', 'no quiero vivir',
  'quiero morir', 'me quiero morir', 'terminar con mi vida'];
const FRASES_URGENCIA = ['dolor de pecho', 'dolor en el pecho', 'duele el pecho', 'dolor toracico', 'no puedo respirar', 'me ahogo', 'desmay',
  'convulsion', 'sobredosis', 'intoxic', 'me tome todas', 'infarto', 'inconsciente', 'no reacciona',
  'sangra mucho', 'sangrado abundante', 'urgencia', 'emergencia', 'accidente'];
const FRASES_CONSEJO = ['dosis', 'cuantas pastillas', 'cuantas tomo', 'cuanto tomo', 'cuantas debo',
  'puedo tomar', 'se puede tomar', 'debo tomar', 'efecto secundario', 'efectos secundarios', 'contraindic',
  'embarazada', 'lactancia', 'para que sirve', 'me duele', 'dolor de', 'sintoma', 'que me recomienda',
  'que tomo para', 'con alcohol', 'puedo mezclar', 'receta medica para', 'diagnost'];

// Palabras de relleno que se quitan antes de buscar el remedio.
const RELLENO = new Set(['hola', 'holi', 'ola', 'alo', 'buenas', 'buenos', 'buen', 'dia', 'dias', 'tardes',
  'noches', 'hay', 'tienen', 'tiene', 'tendran', 'tendra', 'queda', 'quedan', 'stock', 'disponible',
  'disponibles', 'disponibilidad', 'precio', 'precios', 'valor', 'cuanto', 'cuesta', 'cuestan', 'vale',
  'valen', 'sale', 'salen', 'el', 'la', 'los', 'las', 'lo', 'del', 'de', 'un', 'una', 'unos', 'unas', 'me',
  'mi', 'por', 'favor', 'porfa', 'porfis', 'please', 'quiero', 'quisiera', 'necesito', 'necesitaria',
  'busco', 'buscando', 'saber', 'si', 'consultar', 'consulta', 'preguntar', 'pregunta', 'remedio',
  'remedios', 'medicamento', 'medicamentos', 'pastilla', 'pastillas', 'gracias', 'para', 'que', 'y', 'o',
  'a', 'en', 'con', 'ustedes', 'usted', 'ahi', 'alguna', 'alguno', 'algun', 'farmacia', 'comunitaria',
  'oiga', 'senor', 'senora', 'senorita', 'disculpe', 'consultarles', 'les', 'donde', 'puedo', 'comprar',
  'conseguir', 'encontrar', 'venden', 'vende', 'todavia', 'aun', 'ahora', 'hoy']);

function isAuthorized(headers, secret) {
  if (!headers || typeof headers !== 'object') return false;
  if (typeof secret !== 'string' || !secret) return false;
  const key = Object.keys(headers).find(
    (name) => typeof name === 'string' && name.toLowerCase() === 'x-telegram-bot-api-secret-token'
  );
  if (!key) return false;
  const value = headers[key];
  return typeof value === 'string' && value === secret;
}

/** Lista de chat_id separada por comas -> arreglo limpio. */
function parseIdList(list) {
  const raw = typeof list === 'string' ? list : '';
  return raw.split(',').map((s) => s.trim()).filter((s) => s.length > 0);
}

function inList(chatId, list) {
  if (chatId === null || chatId === undefined) return false;
  return parseIdList(list).indexOf(String(chatId)) !== -1;
}

function sinTildes(s) {
  return String(s === null || s === undefined ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '');
}

function contieneAlguna(textoNormalizado, frases) {
  for (let i = 0; i < frases.length; i++) {
    if (textoNormalizado.indexOf(frases[i]) !== -1) return true;
  }
  return false;
}

/** Quita saludos y muletillas; conserva nombres, dosis y unidades. */
function limpiarConsulta(texto) {
  const tokens = sinTildes(texto)
    .replace(/[¿?¡!.,;:()"'*]+/g, ' ')
    .split(/\s+/)
    .filter((t) => t.length > 0);
  return tokens.filter((t) => !RELLENO.has(t)).join(' ').trim();
}

/** Deja el texto desde la palabra de reserva y normaliza "2 cajas" -> "x2". */
function normalizarReserva(texto) {
  let t = String(texto === null || texto === undefined ? '' : texto).trim();
  // Saludo o muletilla antes de la palabra clave: "hola, quiero reservar ..." -> "reservar ..."
  const m = RE_PALABRA_RESERVA.exec(t);
  if (m && limpiarConsulta(t.slice(0, m.index)) === '') t = t.slice(m.index + m[0].indexOf(m[1]));
  t = t.replace(/^(res[eé]rvame|apartar)(?![a-záéíóúñ])/i, 'reservar');
  const coma = t.indexOf(',');
  let cabeza = coma === -1 ? t : t.slice(0, coma);
  const cola = coma === -1 ? '' : t.slice(coma);
  cabeza = cabeza.replace(/(\d{1,3})\s*(cajas?|unidades|unidad|uds?|u)\b/gi, ' x$1 ');
  // Relleno solo en el segmento del producto; nunca toca RUT, dirección ni sector.
  cabeza = cabeza
    .split(/\s+/)
    .filter((w) => w.length > 0)
    .filter((w, i) => i === 0 || !RELLENO.has(sinTildes(w).replace(/[¿?¡!.;:]+/g, '')))
    .join(' ');
  return (cabeza + cola).replace(/\s+,/g, ',').replace(/\s{2,}/g, ' ').trim();
}

/**
 * Es reserva cuando la palabra clave aparece al inicio o precedida solo de
 * saludos y muletillas ("hola, quiero reservar ..."). "el estado de mi
 * reserva" NO es reserva: "estado" no es relleno.
 */
function esReserva(texto) {
  const t = String(texto === null || texto === undefined ? '' : texto);
  const m = RE_PALABRA_RESERVA.exec(t);
  if (!m) return false;
  return limpiarConsulta(t.slice(0, m.index)) === '';
}

function esSoloSaludo(texto) {
  const n = sinTildes(texto).replace(/[¿?¡!.,;:]+/g, ' ').trim();
  if (/^\/?(start|ayuda|help|menu|opciones|inicio)\b/.test(n)) return true;
  return limpiarConsulta(texto) === '' && n.length > 0;
}

function contarPalabras(texto) {
  return texto ? texto.split(/\s+/).filter((t) => t.length > 0).length : 0;
}

/** Copia el update reemplazando message.text (o caption) por el texto normalizado. */
function bodyConTexto(update, texto) {
  const copia = JSON.parse(JSON.stringify(update));
  if (copia.message && typeof copia.message.text === 'string') copia.message.text = texto;
  return copia;
}

/**
 * Decide la intención de UN update. Devuelve el ítem de salida o null.
 * env: { secret, pharmacists, staff, geminiKey }.
 */
function classifyUpdate(update, headers, env) {
  if (!isAuthorized(headers, env.secret)) return null;
  if (!update || typeof update !== 'object') return null;
  const message = update.message;
  if (!message || typeof message !== 'object') return null;
  const chat =
    message.chat && (typeof message.chat.id === 'string' || typeof message.chat.id === 'number')
      ? String(message.chat.id)
      : '';
  if (!chat) return null;

  const staffList = parseIdList(env.staff).length ? env.staff : env.pharmacists;
  const texto = typeof message.text === 'string' ? message.text.trim() : '';
  const caption = typeof message.caption === 'string' ? message.caption.trim() : '';
  const out = {
    intent: 'respuesta',
    motivo: '',
    chat_id: chat,
    reply: '',
    texto_original: texto || caption,
    texto_limpio: '',
    llm_disponible: !!(env.geminiKey && String(env.geminiKey).trim()),
    headers: headers,
    body: update
  };

  // 1) Receta: foto (o imagen enviada como archivo).
  const esImagen =
    (Array.isArray(message.photo) && message.photo.length > 0) ||
    (message.document && /^image\//.test(String(message.document.mime_type || '')));
  if (esImagen) {
    out.intent = 'receta';
    out.motivo = 'foto';
    return out;
  }

  if (!texto) {
    out.motivo = 'sin_texto';
    out.reply = MENSAJES.sin_texto;
    return out;
  }

  // 2-3) Comandos del personal (solo desde chats autorizados).
  if (RE_CMD_FARMACEUTICO.test(texto) && inList(chat, env.pharmacists)) {
    out.intent = 'aprobacion';
    out.motivo = 'comando_farmaceutico';
    return out;
  }
  if (RE_CMD_PERSONAL.test(texto) && inList(chat, staffList)) {
    out.intent = 'despacho';
    out.motivo = 'comando_personal';
    return out;
  }
  if (RE_CMD_EXPIRACION.test(texto) && inList(chat, staffList)) {
    out.intent = 'expiracion';
    out.motivo = 'comando_personal';
    return out;
  }

  // 4-5) Seguridad clínica antes que cualquier intención comercial (RNF-08).
  const n = sinTildes(texto);
  if (contieneAlguna(n, FRASES_AUTOLESION)) {
    out.motivo = 'autolesion';
    out.reply = MENSAJES.autolesion;
    return out;
  }
  if (contieneAlguna(n, FRASES_URGENCIA)) {
    out.motivo = 'urgencia';
    out.reply = MENSAJES.urgencia;
    return out;
  }
  if (contieneAlguna(n, FRASES_CONSEJO)) {
    out.motivo = 'consejo_clinico';
    out.reply = MENSAJES.consejo;
    return out;
  }

  // 6) Saludo o ayuda.
  if (esSoloSaludo(texto)) {
    out.motivo = 'bienvenida';
    out.reply = MENSAJES.bienvenida;
    return out;
  }

  // 7) Reserva (antes que estado: la reserva trae RUT).
  if (esReserva(texto)) {
    const limpio = normalizarReserva(texto);
    out.intent = 'reserva';
    out.motivo = 'palabra_reserva';
    out.texto_limpio = limpio;
    out.body = bodyConTexto(update, limpio);
    return out;
  }

  // 8) Estado: código, RUT o palabra clave.
  if (RE_FAR.test(texto) || RE_RUT.test(texto)) {
    out.intent = 'estado';
    out.motivo = 'codigo_o_rut';
    return out;
  }
  if (RE_ESTADO.test(n)) {
    out.motivo = 'estado_sin_dato';
    out.reply = MENSAJES.estado_sin_dato;
    return out;
  }

  // 9) Fuera del dominio: respuesta honesta en vez de buscar un remedio inexistente.
  if (RE_FUERA_DOMINIO.test(n)) {
    out.motivo = 'fuera_de_dominio';
    out.reply = MENSAJES.fuera_de_dominio;
    return out;
  }

  // 10-11) Consulta de un remedio, o texto ambiguo.
  const limpio = limpiarConsulta(texto);
  out.texto_limpio = limpio;
  if (!limpio) {
    out.motivo = 'bienvenida';
    out.reply = MENSAJES.bienvenida;
    return out;
  }
  if (contarPalabras(limpio) > MAX_PALABRAS_CONSULTA) {
    out.intent = 'ambiguo';
    out.motivo = 'texto_largo';
    out.reply = MENSAJES.no_entendido;
    out.body = bodyConTexto(update, limpio);
    return out;
  }
  out.intent = 'consulta';
  out.motivo = 'nombre_remedio';
  out.body = bodyConTexto(update, limpio);
  return out;
}

// --- ensamblaje n8n (protegido para que el arnés de pruebas cargue las funciones) ---
if (typeof $input !== 'undefined') {
  try {
    const items = $input.all();
    for (let i = 0; i < items.length; i++) {
      const json = items[i] && items[i].json ? items[i].json : items[i];
      const headers = json && json.headers && typeof json.headers === 'object' ? json.headers : {};
      const update = json && json.body && typeof json.body === 'object' ? json.body : json;
      const out = classifyUpdate(update, headers, {
        secret: $env.TELEGRAM_WEBHOOK_SECRET,
        pharmacists: $env.TELEGRAM_PHARMACIST_CHAT_IDS,
        staff: $env.TELEGRAM_STAFF_CHAT_IDS,
        geminiKey: $env.GEMINI_API_KEY
      });
      if (out) return [{ json: out }];
    }
  } catch (err) {
    return [];
  }
  return [];
}

/**
 * US-17 — aplicar_llm (respaldo opcional con Gemini).
 *
 * Solo se ejecuta cuando las reglas dejaron el mensaje como "ambiguo" y hay
 * GEMINI_API_KEY. Gemini SOLO elige una etiqueta de una lista cerrada; nunca
 * redacta la respuesta ni aporta nombres, precios o stock (riesgo R-02). Toda
 * respuesta sale de los textos fijos del router o de los subflujos, que leen
 * la planilla. Si Gemini falla, demora o responde algo fuera de la lista, se
 * mantiene el menú de ayuda (degradación elegante).
 *
 * Etiquetas: consulta | estado | reserva | ayuda | urgencia | consejo.
 */
const ETIQUETAS = ['consulta', 'estado', 'reserva', 'ayuda', 'urgencia', 'consejo'];

const RESPUESTAS = {
  urgencia:
    'Si es una urgencia, llame ahora al SAMU 131 o acuda al SAPU más cercano. ' +
    'Este asistente no puede atender emergencias médicas.',
  consejo:
    'No puedo dar indicaciones sobre dosis, síntomas ni tratamientos. Consulte a su médico o al ' +
    'químico farmacéutico de la farmacia. Si es una urgencia, llame al SAMU 131.',
  estado:
    'Para ver su pedido, escriba su código (por ejemplo: estado #FAR-0001) o su RUT (por ejemplo: 11.111.111-1).',
  reserva:
    'Para reservar escriba en un solo mensaje: reservar [remedio] x[cantidad] rut [su RUT], [dirección], [sector]. ' +
    'Por ejemplo: reservar neurogab 75 x1 rut 11.111.111-1, Av. Grecia 8735, Peñalolén Alto.'
};

/** Extrae la etiqueta de la respuesta de Gemini; null si no es válida. */
function etiquetaDesdeGemini(respuesta) {
  try {
    const parts =
      respuesta && respuesta.candidates && respuesta.candidates[0] &&
      respuesta.candidates[0].content && respuesta.candidates[0].content.parts;
    const texto = Array.isArray(parts) ? parts.map((p) => (p && p.text) || '').join(' ') : '';
    const limpio = String(texto).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
      .replace(/[^a-z]/g, ' ').trim().split(/\s+/)[0] || '';
    return ETIQUETAS.indexOf(limpio) !== -1 ? limpio : null;
  } catch (err) {
    return null;
  }
}

/**
 * Aplica la etiqueta sobre el ítem clasificado. Solo "consulta" deriva a un
 * subflujo; el resto responde con un texto fijo. Sin etiqueta válida, se
 * mantiene la respuesta "no entendido" ya preparada por clasificar.
 */
function aplicarEtiqueta(clasificado, etiqueta) {
  const out = Object.assign({}, clasificado, { llm_etiqueta: etiqueta || '' });
  if (!etiqueta || etiqueta === 'ayuda') {
    out.intent = 'respuesta';
    out.motivo = etiqueta ? 'llm_ayuda' : 'llm_sin_etiqueta';
    return out;
  }
  if (etiqueta === 'consulta') {
    out.intent = 'consulta';
    out.motivo = 'llm_consulta';
    out.reply = '';
    return out;
  }
  out.intent = 'respuesta';
  out.motivo = 'llm_' + etiqueta;
  out.reply = RESPUESTAS[etiqueta] || out.reply;
  return out;
}

// --- ensamblaje n8n ---
if (typeof $ !== 'undefined' && typeof $input !== 'undefined') {
  let clasificado = null;
  try {
    clasificado = $('clasificar').first().json;
  } catch (err) {
    clasificado = null;
  }
  if (!clasificado) return [];
  const etiqueta = etiquetaDesdeGemini($input.first().json);
  return [{ json: aplicarEtiqueta(clasificado, etiqueta) }];
}
